// Dipakai pada halaman /nota/detail/{id} (pembayaran satu nota) dan /nota/bayar (seluruh pembayaran)
const $tabelBayar = $('#tabelBayar'),
    $formBayar = $('#formBayar'),
    $modalBayar = $('#modalBayar'),
    bayarCek = CirebonwebForm.FormCek($formBayar);

// Fungsi utama kalkulasi pembayaran
function hitungPembayaran() {
    // 1. Ambil nilai & konversi dari format Rupiah ke angka murni (Integer)
    let notaTotal = parseInt(CirebonwebFormat.unRupiah($('#nota_total').val())) || 0;
    let uangTerima = parseInt(CirebonwebFormat.unRupiah($('#uang_terima').val())) || 0;

    // 2. Terapkan batasan: Uang Bayar tidak boleh lebih besar dari Nota Total
    let uangBayar = Math.min(uangTerima, notaTotal);

    // 3. Hitung Sisa Nota dan Uang Kembali
    let notaSisa = notaTotal - uangBayar;
    let uangKembali = uangTerima > notaTotal ? uangTerima - notaTotal : 0;

    // 4. Update nilai input dengan format Rupiah
    $('#uang_bayar').val(CirebonwebFormat.Rupiah(uangBayar));
    $('#nota_sisa').val(CirebonwebFormat.Rupiah(notaSisa));
    $('#uang_kembali').val(CirebonwebFormat.Rupiah(uangKembali));
}

// Tabel nota_bayar
$(function () {
    if (!$tabelBayar.length) return;

    $tabelBayar.DataTable({
        processing: true,
        serverSide: true,
        ajax: {
            url: `${urlBayar}/tabel`,
            type: 'POST',
            data: function (d) {
                if (notaId > 0) d.nota_id = notaId;
            }
        },
        autoWidth: false,
        scrollX: false,
        responsive: true,
        searching: false,
        ordering: false,
        lengthChange: false,
        paging: false,
        info: false,
        dom: 'Brtip',
        buttons: [
            { text: 'Add', action: () => { simpanBayar(); } },
            {
                text: 'Reload',
                action: function (e, dt) {
                    Swal.fire({ icon: 'success', title: 'Informasi', text: 'Selesai reload tabel ke kondisi awal', showConfirmButton: false, timer: 1300 })
                        .then(function () { dt.ajax.reload(null, true); });
                }
            },
        ],
        columnDefs: [
            { targets: '_all', className: 'dt-head-center' },
            { targets: [0, 3], className: 'dt-body-center' },
            { targets: [4, 5, 6], className: 'dt-body-right', orderable: false },
            { targets: [4, 5, 6], render: CirebonwebFormat.RupiahTabel },
            { targets: [2, 8, 9], render: (data) => CirebonwebFormat.Tanggal(data) },
            { targets: 10, orderable: false, render: (data) => (notaId > 0 && notaStatus === 3) ? 'Null' : data },
        ]
    });

    // Trigger setiap kali input berubah
    $('#tgl_bayar').datepicker({ dateFormat: 'dd-mm-yy' });
    // Jalankan kalkulasi saat input #uang_terima atau #nota_total berubah
    $('#uang_terima, #nota_total').on('input', function () {
        hitungPembayaran();
    });
    $modalBayar.on('shown.bs.modal', function () { bayarCek.resetInitial(); }).on('hidden.bs.modal', function () { CirebonwebForm.FormReset(this); });
});


// Upload file bukti transfer
$(function () {
    let $dropzone = $('#dropzone_area');
    let $fileInput = $('#bukti_transfer');

    // Klik area dropzone akan men-trigger klik pada input file
    $dropzone.on('click', function () {
        $fileInput.click();
    });

    // Indikator visual saat file diseret di atas area
    $dropzone.on('dragover dragenter', function (e) {
        e.preventDefault();
        e.stopPropagation();
        $(this).addClass('bg-white border-primary');
    });

    $dropzone.on('dragleave dragend drop', function (e) {
        e.preventDefault();
        e.stopPropagation();
        $(this).removeClass('bg-white border-primary');
    });

    // Saat file di-drop ke area
    $dropzone.on('drop', function (e) {
        let files = e.originalEvent.dataTransfer.files;
        if (files.length > 0) {
            $fileInput[0].files = files; // Set file ke input HTML
            tampilkanNamaFile(files[0]);
        }
    });

    // Saat file dipilih manual lewat dialog browser
    $fileInput.on('change', function () {
        if (this.files.length > 0) {
            tampilkanNamaFile(this.files[0]);
        }
    });

    function tampilkanNamaFile(file) {
        $('#file_name_preview').text('File terpilih: ' + file.name);
    }
});

