// Ringkasan nota dihitung oleh trigger; di halaman nota diperbarui lewat AJAX
function segarkanHalaman() {
    if (notaId > 0 && typeof segarkanRingkasanNota === 'function') {
        segarkanRingkasanNota();
    }
}

// Form Submit (Insert/Update)
function simpanBayar(id) {
    if (!$formBayar.length) return;

    const isEdit = id > 0;
    const $modalTitle = $modalBayar.find('.modal-title'),
        $btnSubmit = $('#btnSubmitBayar'),
        postUrl = `${urlBayar}/simpan`;

    if (isEdit) {
        CirebonwebForm.FormFetch(`${bayarUrl}/getid`, { id }, 'POST', {}).done(function (response) {
            if (!response.success) return;
            const data = response.data;
            $modalTitle.text('Edit Data');
            $btnSubmit.text('Update');
            $formBayar.find('#bayar_id').val(data.id);
            $formBayar.find('#bayar_nota_id').val(data.nota_id);
            $formBayar.find('#metode_bayar').val(data.metode_bayar);
            CirebonwebFormat.isoTanggal('#tgl_bayar', data.tgl_bayar);
            $formBayar.find('#uang_terima').val(CirebonwebFormat.Rupiah(data.uang_terima));
            $formBayar.find('#uang_bayar').val(CirebonwebFormat.Rupiah(data.uang_bayar));
            // hitungKembalian();
            $modalBayar.modal('show');
        });
    } else {
        $modalTitle.text('Tambah Data');
        $btnSubmit.text('Simpan');
        // FormReset mengosongkan input hidden, jadi id nota dipasang ulang
        // $formBayar.find('#bayar_nota_id').val(notaId);
        $formBayar.find('#tgl_bayar').val(CirebonwebFormat.Tanggal(new Date(), 'tanggal'));
        // $formBayar.find('#bayar_diterima, #bayar_jumlah').val(CirebonwebFormat.Rupiah(0));
        // $formBayar.find('#bayar_kembalian').val('0');

        // let netTotalVal = CirebonwebFormat.unRupiah($('.rpNetTotal').text().trim());
        // let netTotalVal = CirebonwebFormat.unRupiah($('.rpNetTotal').text().trim());
        // $formBayar.find('#bayar_jumlah').val(netTotalVal);
        $formBayar.find('#nota_total').val($('.rpNetTotal').text().trim());
        $formBayar.find('#nota_sisa').val($('.rpSisa').text().trim());

        $modalBayar.modal('show');
    }

    $formBayar.validate($.extend(CirebonwebForm.FormValidasi(), {
        rules: {
            nota_id: { required: true, digits: true },
            tgl_bayar: { required: true },
            uang_terima: { required: true },
            uang_bayar: { required: true },
        },
        submitHandler: function () {
            if (!bayarCek.isChanged()) return false;

            const data = $formBayar.serializeArray();
            data.forEach(function (item) {
                if (['uang_terima', 'uang_bayar'].includes(item.name)) {
                    item.value = CirebonwebFormat.unRupiah(item.value);
                } else if (item.name === 'tgl_bayar') {
                    item.value = CirebonwebFormat.sqlTanggal(item.value);
                }
            });

            CirebonwebForm.FormFetch(postUrl, data, 'POST', {
                before_call: function () {
                    $btnSubmit.attr('disabled', true).html('<span class="spinner-border spinner-border-sm mr-1"></span> Loading...');
                },
                after_call: function () { $btnSubmit.attr('disabled', false).html('Simpan'); }
            }).done(function (response) {
                if (!response.success) return;
                $modalBayar.modal('hide');
                Swal.fire({ icon: 'success', title: 'Sukses', html: response.messages, showConfirmButton: false, timer: 1300 })
                    .then(function () {
                        $tabelBayar.DataTable().ajax.reload(null, false);
                        segarkanHalaman();
                    });
            });
            return false;
        }
    }));
}

// Form Submit (Delete)
function hapusBayar(id) {
    Swal.fire({
        title: 'Konfirmasi',
        html: 'Apakah yakin ingin menghapus data ini? <br> Data akan dihapus secara permanen!',
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#d33',
        confirmButtonText: 'Ya, hapus!'
    }).then(function (result) {
        if (!result.isConfirmed) return;
        CirebonwebForm.FormFetch(`${bayarUrl}/hapus`, { id }, 'POST', {}).done(function (response) {
            if (!response.success) return;
            Swal.fire({ icon: 'success', title: 'Sukses', html: response.messages, showConfirmButton: false, timer: 1300 })
                .then(function () {
                    $tabelBayar.DataTable().ajax.reload(null, false);
                    segarkanHalaman();
                });
        });
    });
}
